#include <stdio.h>
#include <stdlib.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    if (n <= 2) { puts("0"); return 0; }
    long long *h = (long long*)malloc(n * sizeof(long long));
    for (int i = 0; i < n; i++) scanf("%lld", &h[i]);
    int l = 0, r = n - 1;
    long long max_l = h[l], max_r = h[r], water = 0;
    while (l < r) {
        if (max_l <= max_r) {
            l++;
            if (h[l] > max_l) max_l = h[l];
            else water += max_l - h[l];
        } else {
            r--;
            if (h[r] > max_r) max_r = h[r];
            else water += max_r - h[r];
        }
    }
    printf("%lld\n", water);
    free(h);
    return 0;
}

