import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n <= 2) { System.out.println(0); return; }
            long[] h = new long[n];
            for (int i = 0; i < n; i++) h[i] = sc.nextLong();
            int l = 0, r = n - 1;
            long maxL = h[l], maxR = h[r], water = 0;
            while (l < r) {
                if (maxL <= maxR) {
                    l++;
                    if (h[l] > maxL) maxL = h[l];
                    else water += maxL - h[l];
                } else {
                    r--;
                    if (h[r] > maxR) maxR = h[r];
                    else water += maxR - h[r];
                }
            }
            System.out.println(water);
        }
    }
}

