const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/).map(Number);
    if (toks.length > 0) {
        const n = toks[0];
        const h = toks.slice(1, 1 + n);
        if (n <= 2) { console.log(0); return; }
        let l = 0, r = n - 1, maxL = h[l], maxR = h[r], water = 0;
        while (l < r) {
            if (maxL <= maxR) {
                l++;
                maxL = Math.max(maxL, h[l]);
                water += maxL - h[l];
            } else {
                r--;
                maxR = Math.max(maxR, h[r]);
                water += maxR - h[r];
            }
        }
        console.log(water);
    }
}
main();

